import{_ as a,o,c as r,a2 as e}from"./chunks/framework.DnrXFDHb.js";const q=JSON.parse('{"title":"中恒电气 vs 台达电：供电架构升级的双雄对比","description":"","frontmatter":{"title":"中恒电气 vs 台达电：供电架构升级的双雄对比","updated":"2026-08-21T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/中恒电气vs台达电_供电架构升级双雄对比.md","filePath":"智算中心投建运/中恒电气vs台达电_供电架构升级双雄对比.md","lastUpdated":null}'),n={name:"智算中心投建运/中恒电气vs台达电_供电架构升级双雄对比.md"};function i(p,t,l,s,u,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<p><strong>封面 title：中恒电气 vs 台达电</strong></p><p><strong>主标题：台达赚现在的钱，中恒赌未来的斜率：800V 直流切换的两种活法</strong></p><p>营收差 59 倍，净利润差 109 倍，市值却只差 46 倍——这是台达电和中恒电气 2026 年 8 月的真实对照。一家是营收 1500 亿元人民币量级的全球电源巨头，一家是年净利 1.26 亿元的国内 HVDC 冠军。把它们放在一起比较，不是为了分大小，而是因为它们押注的是同一场变革：数据中心的供电架构，正在从交流 UPS 切换为 800V 高压直流。这场切换对两家公司意味着什么？答案完全不同。</p><hr><h2 id="一、同一个赛道-两种体量" tabindex="-1">一、同一个赛道，两种体量 <a class="header-anchor" href="#一、同一个赛道-两种体量" aria-label="Permalink to &quot;一、同一个赛道，两种体量&quot;">​</a></h2><p>先看基本面的事实层。</p><p>台达电 2025 年营收 5549 亿新台币（约 1271 亿元人民币），净利 601 亿新台币，毛利率 34.3%；过去 12 个月营收增速 47.7%，2026 年一季度净利 206 亿新台币、同比翻倍（数据来源：Yahoo Finance 2308.TW，截至 2026-08-20）。这是 AI 电源需求直接打在报表上的样子。</p><p>中恒电气 2025 年营收 21.37 亿元，归母净利 1.26 亿元，毛利率 24.8%，ROE 只有 5.2%；其中数据中心电源收入 7.76 亿元（+16%），是最大业务板块（数据来源：iFinD 002364.SZ 2025 年报，截至 2026-08-20）。2026 年一季度，营收 4.18 亿元、归母净利 2494 万元——弹性还没有出现在报表上。</p><p>但市场的定价是反过来的：中恒电气静态市盈率 176 倍，按券商 2026 年一致预期（归母净利 2.66 亿元、+110%）折算约 84 倍；台达电 TTM 市盈率 55.5 倍，远期只有 27 倍（iFinD 盈利预测、Yahoo Finance，2026-08-20；本刊计算）。给&quot;期权&quot;的估值是给&quot;现金牛&quot;的三倍。要理解这个倒挂，得拆开两家公司的商业模式。</p><hr><h2 id="二、台达电-全球总包商-ai-的钱已经在报表里" tabindex="-1">二、台达电：全球总包商，AI 的钱已经在报表里 <a class="header-anchor" href="#二、台达电-全球总包商-ai-的钱已经在报表里" aria-label="Permalink to &quot;二、台达电：全球总包商，AI 的钱已经在报表里&quot;">​</a></h2><p>台达电的模式可以概括为&quot;全球 AI 电源总包商&quot;。它的生意不挑客户——从英伟达到全球云厂商，从服务器机内电源到数据中心基础设施，AI 资本开支的每一美元里都有它的抽成。</p><p>三个证据说明这种模式正处在收获期。第一，2026 年一季度净利同比 +102%，营收 +34%——利润增速是收入增速的三倍，说明 AI 电源的产品结构在拉高盈利质量。第二，2026 年二季度，电源电子事业群同比增长 50%，是四大事业群里最快的一块；基础设施事业群受数据中心液冷和基建拉动同步高增（知乎财报解读，2026Q2）。第三，盈利能力的绝对水平：TTM 毛利率 35.5%、营业利益率 16.7%、ROE 30%——这是一台每分钟都在印钞的机器。</p><p>护城河的来源是生态绑定。英伟达 2025 年 5 月发布 800V HVDC 架构时，台达是其供应商联盟的核心成员；在数据中心电源这个全球约 95% 份额由台达、维谛等少数厂商占据的市场里（行业研报口径），规模和客户信任本身就是壁垒——它一年 487 亿新台币的研发投入（约 112 亿元人民币），比中恒电气的全部营收还多五倍。</p><p>风险同样清楚。一是估值：55 倍 TTM 市盈率已经把 AI 景气定价得比较充分，52 周股价涨幅 172% 之后，任何全球 AI 资本开支的减速信号都会直接打在估值上。二是份额保卫：2026 年年中台达泰国工厂的产品事件，让柜内电源的国产替代者看到了机会窗口——不过需要说清楚，这类事件的受益者是麦格米特这类机内电源厂商，而不是做机房级供电系统的中恒电气，两者战场不同。</p><hr><h2 id="三、中恒电气-标准制定者的制度红利" tabindex="-1">三、中恒电气：标准制定者的制度红利 <a class="header-anchor" href="#三、中恒电气-标准制定者的制度红利" aria-label="Permalink to &quot;三、中恒电气：标准制定者的制度红利&quot;">​</a></h2><p>中恒电气的模式完全不同——它的护城河不是规模，而是&quot;标准 + 排他性客户绑定&quot;构成的制度性卡位。</p><p>这家公司牵头制定了信息通信 240V/336V 直流供电系统的国家标准，入选工信部制造业单项冠军；它的巴拿马电源把 10kV 中压交流一步转成直流，将传统四级供电链路压缩为一级，系统效率 97.5% 以上，单套系统可支持 2.5MW IT 负载（公司 2025 年报）。在阿里巴巴生态里，巴拿马电源份额超过 90%；2025 年它中标了阿里的巴拿马 2.0 电源、腾讯的弹性直流系统、字节的精密配电、中国银行的 HVDC 项目；2026 年字节首次在招标中引入 800V HVDC 架构时，试点方案指定使用其技术产品（据雪球援引招标信息，2026-04）。</p><p>2025 年 10 月，中恒孙公司 SuperX 发布了 Panama-800VDC 与 Aurora-800VDC 两款旗舰产品，分别面向新建和改造场景，端到端效率最高可达 98.5%。一个值得注意的细节是：在全球巴拿马电源市场的主要厂商名单里，台达和 SuperX 同时出现——两岸两家公司在同一个细分品类里短兵相接。</p><p>但必须直视报表的另一面：2025 年数据中心电源毛利率 20.7%，同比下降 1.4 个百分点；整体 ROE 只有 5.2%，是台达的六分之一。市占率第一，不等于赚钱能力第一。中恒当前的本质，是一家盈利能力平庸的设备商，持有一张&quot;国内 800V 渗透率从 10% 走向 70%&quot;的看涨期权。券商一致预期 2026 年净利翻倍，就是这张期权开始定价的信号——而 2026Q3 的 800V 小批量出货，是第一个可以验证的行权节点。</p><hr><h2 id="四、差异的根源-客户结构决定商业模式" tabindex="-1">四、差异的根源：客户结构决定商业模式 <a class="header-anchor" href="#四、差异的根源-客户结构决定商业模式" aria-label="Permalink to &quot;四、差异的根源：客户结构决定商业模式&quot;">​</a></h2><p>为什么同一条技术曲线，长出两种公司？</p><p>根源在客户结构。台达面对的是全球分散的云厂商和 AI 生态，生意的本质是&quot;每瓦电源价值量 × 全球 AI 装机量&quot;——量大、稳定、可预期，所以市场给它现金牛的估值逻辑。中恒面对的是国内少数几家超级云厂商，生意的本质是&quot;标准话语权 × 客户资本开支节奏&quot;——集中、波动、但一旦渗透率陡峭化，弹性极大。</p><p>出海路径的对照更能说明问题。中恒的打法是借船：2022 年起与施耐德持续深化合作，其 800VDC 产品已获施耐德认可，2026 年双方合作进入新阶段——通过施耐德的全球渠道把 HVDC 产品推向海外（东方财富证券年报点评，2026-04）。台达的打法是上岸：2025 年 11 月，它与美团、秦淮数据、东阳光联合打造固态变压器直流供电系统方案，已在国内数据中心园区落地——用 SST 这张下一张船票卡位中国市场。</p><p>竞争与错位并存：台达守全球，中恒守国内；台达的风险在全球 AI 大盘的 beta，中恒的风险在国内渗透率的 alpha 能否兑现。</p><hr><h2 id="五、谁更可持续-三情景与一个观测点" tabindex="-1">五、谁更可持续：三情景与一个观测点 <a class="header-anchor" href="#五、谁更可持续-三情景与一个观测点" aria-label="Permalink to &quot;五、谁更可持续：三情景与一个观测点&quot;">​</a></h2><p><strong>基准情景</strong>：2026Q3 起 800V 小批量出货、2027 年随英伟达 Rubin Ultra 放量。中恒兑现 2026E 一致预期，期权开始向业绩转化；台达维持 40% 以上的营收增速，估值压力被盈利增长消化。</p><p><strong>乐观情景</strong>：国内 800V 招标规模超预期，施耐德代工落地。中恒从&quot;国内冠军&quot;重估为&quot;全球代工 + 自主品牌&quot;双模式；台达电源事业群维持 +50% 增速。</p><p><strong>悲观情景</strong>：±400V 过渡方案分流、标准博弈延迟一到两年。中恒的期权定价回撤——这是两者中受伤更重的一方；台达有全球 AI 资本开支托底，回撤相对有限。</p><p>对国内产业的启示是：HVDC 这条赛道上，中国企业已经同时具备&quot;标准制定者&quot;（中恒牵头国标）和&quot;全球主力供应商&quot;（台达、SuperX 同列巴拿马电源国际主要厂商）两种角色。800V 切换越确定，全球总包商赚得越稳；国内渗透越快，标准制定者的斜率越陡。下一个观测点很清楚：2026Q3，第一批 800V 小批量订单流向谁。</p><hr><h2 id="风险提示" tabindex="-1">风险提示 <a class="header-anchor" href="#风险提示" aria-label="Permalink to &quot;风险提示&quot;">​</a></h2><ul><li><strong>渗透率不及预期</strong>：±400V 过渡方案拉长、800V 标准分裂，中恒电气的弹性逻辑将被证伪；</li><li><strong>AI 资本开支波动</strong>：全球云厂商 CapEx 减速将同时冲击两者，台达高估值下回撤更敏感；</li><li><strong>中恒盈利质量风险</strong>：毛利率承压、增收不增利的可能存在，2026Q1 净利率仅约 6%；</li><li><strong>数据口径风险</strong>：市占率、渗透率均为多机构测算口径，实际节奏可能偏离；</li><li><strong>台达份额事件</strong>：泰国产品事件对柜内电源份额的影响有待后续财报验证。</li></ul><hr><p><em>本文数据截至 2026 年 8 月 20 日。本文仅为产业研究，不构成任何投资建议。</em></p><hr><h2 id="附-发布信息-粘贴草稿箱时参考" tabindex="-1">附：发布信息（粘贴草稿箱时参考） <a class="header-anchor" href="#附-发布信息-粘贴草稿箱时参考" aria-label="Permalink to &quot;附：发布信息（粘贴草稿箱时参考）&quot;">​</a></h2><p><strong>公众号摘要（116 字）</strong>：营收差 59 倍、净利差 109 倍，市值只差 46 倍。台达电与中恒电气押注同一场 800V 直流切换：一个绑定英伟达赚全球 AI 电源现在的钱，一个制定国标赌国内渗透率从 10% 到 70% 的斜率钱。本文拆透两种模式的胜负手。</p><p><strong>封面图建议</strong>：左右对半构图——左侧台达电全球供应链地图元素、右侧中恒电气国标文件与巴拿马电源机柜元素，中间一道&quot;800V&quot;电流符号贯穿。封面文案：&quot;营收差 59 倍，市值只差 46 倍。&quot;</p><p><strong>参考来源（分级）</strong></p><ul><li>S 级：中恒电气 2025 年年度报告（深交所披露）；公司财务数据经 iFinD 提取核对（002364.SZ，截至 2026-08-20）</li><li>A 级：Yahoo Finance 台达电（2308.TW）年度/季度财务报表与公司信息（截至 2026-08-20）；国盛证券 HVDC 行业研报（2026-06）；东方财富证券中恒电气年报点评（2026-04）；知乎台达电 2026Q2 财报解读</li><li>B 级：财联社等关于字节跳动 800V HVDC 招标的报道（2026-01）；雪球援引字节招标技术方案信息（2026-04）</li><li>说明：新台币兑人民币按 0.229 折算（2026 年 8 月约值）；中恒 HVDC 市占率存在 28%–50%+ 多口径，正文未取单点数值</li></ul><p><strong>发布提醒</strong>：按《人工智能生成合成内容标识办法》，发布前请在公众号平台完成 AI 生成内容标识操作；中恒电气 2026 中报临近披露，若发布前中报已出，请更新正文相关数据。</p>',45)])])}const d=a(n,[["render",i]]);export{q as __pageData,d as default};
